import { exercises, createWorkout, logSet, finishWorkout, metrics, loadRows } from './workout-state.js';
import { icon, safe, closeSheet, react, toast } from './nap.js';
const $=s=>document.querySelector(s);
let workout=createWorkout(), selected=0, editing=null, view='active', restUntil=0, callbacks;
const overlay=document.createElement('section');overlay.className='workout-screen';overlay.hidden=true;overlay.setAttribute('aria-label','Edzés');$('.device').append(overlay);
const n=v=>v.toLocaleString('hu-HU',{maximumFractionDigits:1});
const clock=seconds=>`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;
const ticks=()=>`<div class="workout-ticks">${workout.sets.flat().map(s=>`<i class="${s?'done':''}"></i>`).join('')}</div>`;
const diagram=()=>`<svg class="gym-art" viewBox="0 0 300 180" aria-hidden="true"><defs><linearGradient id="gym-metal" x2=".3" y2="1"><stop stop-color="#e8e4f3"/><stop offset=".35" stop-color="#71798c"/><stop offset=".65" stop-color="#292c3b"/><stop offset="1" stop-color="#a7adbc"/></linearGradient></defs><ellipse cx="153" cy="154" rx="102" ry="12" fill="#000" opacity=".4"/><g transform="translate(25 0) rotate(-12 150 90)"><path d="M66 130L49 155M178 127L194 155" stroke="url(#gym-metal)" stroke-width="9" stroke-linecap="round"/><path d="M48 119L180 116" stroke="#9bb66b" stroke-width="19" stroke-linecap="round"/><path d="M58 57V142M191 57V142" stroke="url(#gym-metal)" stroke-width="7"/><path d="M20 63H235" stroke="url(#gym-metal)" stroke-width="8"/><g fill="url(#gym-metal)" stroke="#c5dba1" stroke-width="1"><rect x="32" y="35" width="16" height="55" rx="5"/><rect x="49" y="29" width="20" height="68" rx="7"/><rect x="188" y="29" width="20" height="68" rx="7"/><rect x="209" y="35" width="16" height="55" rx="5"/></g><path d="M88 107L148 107" stroke="#d1e9a3" stroke-width="3" stroke-linecap="round"/></g><circle cx="251" cy="30" r="17" fill="#c8e89514" stroke="#c8e89544"/><path d="M246 30L250 34 257 25" stroke="#c8e895" fill="none" stroke-width="2"/></svg>`;
function leave(){overlay.hidden=true;$('.device').classList.remove('in-workout');callbacks?.refresh();requestAnimationFrame(()=>document.querySelector('[data-workout]')?.focus());}
export function openWorkout(){closeSheet();if(!workout.startedAt)workout.startedAt=Date.now();if(workout.status==='ready')workout.status='active';view=workout.status==='complete'?'complete':'active';overlay.hidden=false;$('.device').classList.add('in-workout');render();}
const action=(label,attr,secondary=false)=>`<button class="workout-action ${secondary?'secondary':''}" ${attr}>${label}</button>`;
function render(){
 const m=metrics(workout),ex=exercises[selected];overlay.style.setProperty('--exercise-color',ex.color);
 overlay.innerHTML=`<div class="workout-scroll"><header class="workout-header"><button data-session-leave aria-label="Vissza az edzés Mai oldalára">‹</button><span><small>EDZÉS · DEMÓ</small><strong>Felsőtest A</strong></span><span class="session-clock" data-session-clock></span></header>${view==='active'?active(ex,m):summary(m)}</div>`;
 overlay.querySelector('.workout-scroll').scrollTop=0;updateTimers();
 requestAnimationFrame(()=>overlay.querySelector('h1')?.focus());
}
function active(ex,m){
 const rows=workout.sets[selected];const next=editing??rows.findIndex(s=>!s),full=next<0,values=full?ex:rows[next]||ex;
 return `<div class="session-progress"><span><b>${m.count}</b> / 9 szett<span>3. hét · építkezés</span></span>${ticks()}</div>
 <div class="exercise-switch">${exercises.map((e,i)=>`<button data-exercise="${i}" aria-pressed="${selected===i}"><span>0${i+1}</span>${e.muscle}<small>${workout.sets[i].filter(Boolean).length}/3</small></button>`).join('')}</div>
 <div class="exercise-title"><span class="overline">${ex.muscle} · HYPERTROPHY</span><h1 tabindex="-1">${ex.name}</h1><span class="exercise-prescription">3 × ${ex.reps} <i>·</i> ${ex.rir} RIR <i>·</i> ${clock(ex.rest)} pihenő</span></div>
 <div class="coach-strip"><span class="coach-spark">✦</span><p>${ex.cue}</p></div>
 <div class="previous-set"><span>MÚLT ALKALOM</span><strong>${ex.last}</strong></div>
 <div class="rest-card" id="rest-card" ${restUntil>Date.now()?'':'hidden'}><span class="rest-orbit">◷</span><span><small>PIHENŐ</small><strong data-rest-clock></strong></span><button data-rest-skip>Pihenő vége →</button></div>
 <section class="set-console"><div class="console-heading"><span class="overline">${full?'GYAKORLAT KÉSZ':editing!==null?'SZETT PONTOSÍTÁSA':`${next+1}. MUNKASOROZAT`}</span><span class="target-chip">${selected===0?'+2,5 kg a múlt alkalomhoz':'A saját tempódban'}</span></div>
 ${full?`<div class="exercise-done">${icon('gem')}<strong>Ez a három már a tiéd.</strong><p>Jöhet a következő gyakorlat, vagy nézz vissza a szettekre.</p></div>${action(selected<2?'Következő gyakorlat →':'Edzés összegzése →',selected<2?`data-exercise="${selected+1}"`:'data-session-summary')}`:
 `<form id="workout-set-form"><div class="big-fields">${numberField('kg','SÚLY · KG',values.kg,2.5,0,500)}${numberField('reps','ISMÉTLÉS',values.reps,1,1,100)}</div><div class="rir-field"><label for="set-rir">Mennyi maradt benned?<small>RIR · ismétlés tartalékban</small></label><input id="set-rir" name="rir" type="number" min="0" max="10" step="1" value="${values.rir}" required></div>${action(editing!==null?'Pontosítás mentése ✓':'Szett rögzítése ✓','type="submit"')}<p id="set-error" role="alert"></p></form>`}</section>
 <div class="set-history"><div class="history-heading"><h2>A mai szettjeid</h2><span>Koppints a javításhoz</span></div><div class="set-table-head"><span>SZETT</span><span>KG</span><span>REP</span><span>RIR</span><span></span></div>${rows.map((s,i)=>`<button class="set-table-row ${s?'logged':''}" ${s?`data-edit-set="${i}"`:'disabled'} aria-label="${i+1}. szett${s?' javítása':''}"><span>0${i+1}</span><strong>${s?n(s.kg):'—'}</strong><strong>${s?s.reps:'—'}</strong><span>${s?s.rir:'—'}</span><b>${s?'✓':'·'}</b></button>`).join('')}</div>
 <button class="finish-link" data-session-summary ${m.count?'':'disabled'}>Mára ennyi · összegzés →</button><p class="workout-footnote">Mintaedzés · a demó újratöltése törli a szetteket.</p>`;
}
function numberField(name,label,value,step,min,max){return `<label class="number-box"><span>${label}</span><input aria-label="${name==='kg'?'Súly kilogrammban':'Ismétlések száma'}" name="${name}" type="number" min="${min}" max="${max}" step="${name==='kg'?'.5':'1'}" value="${value}" required><span class="number-controls"><button type="button" data-step="${-step}" data-field="${name}" aria-label="${label} csökkentése">−</button><button type="button" data-step="${step}" data-field="${name}" aria-label="${label} növelése">+</button></span></label>`;}
function summary(m){const done=workout.status==='complete';return `<section class="harvest ${done?'closed':''}"><span class="overline">${done?'EDZÉS LEZÁRVA':'NÉZZ VISSZA EGY PILLANATRA'}</span><div class="harvest-art">${icon('gem')}<i></i><i></i><i></i></div><h1 tabindex="-1">${done?'Beletetted. Megmarad.':'Ennyit tettél bele.'}</h1><div class="harvest-number">${m.count}<small>munkasorozat</small></div><div class="harvest-stats"><span><b>${m.reps}</b>ismétlés</span><span><b>${n(m.volume)}</b>kg × rep*</span><span><b>+${m.xp}</b>demó XP${done?'':' várható'}</span></div></section>
 <div class="coach-strip"><span class="coach-spark">✦</span><p>${m.count===9?'Mind a kilenc tervezett szett megvan. Most hagyj időt annak is, hogy ebből erő legyen.':`${m.count} szettet rögzítettél a tervezett kilencből. Az elvégzett munka így is számít.`}</p></div>
 <div class="summary-exercises">${exercises.map((e,i)=>`<div><span class="overline">${e.name}</span><p>${workout.sets[i].map((s,j)=>s?`<span>${j+1}. ${n(s.kg)} × ${s.reps}<small>${s.rir} RIR</small></span>`:'').join('')||'<small>Nem logoltál szettet.</small>'}</p></div>`).join('')}</div>
 ${done?`<div class="note-card">${safe(workout.note)||'A mai edzésed a helyén.'}</div>${action('Megnézem a heti terhelésem →','data-session-load')}`:
 `<label class="closing-note">Milyen volt ma?<textarea id="closing-note" maxlength="1000" placeholder="Egy mondat magadnak és Mezonak…">${safe(workout.note)}</textarea></label>${action('Edzés lezárása ✓','data-session-finish')}${action('Vissza a szettekhez','data-session-back',true)}`}
 <p class="workout-footnote">* A beírt súly × ismétlés összege. Nem összehasonlítható izomterhelés.<br>Az XP és Mezo visszajelzése bemutató; nincs backend vagy AI-hívás.</p>`;}
function updateTimers(){if(overlay.hidden)return;const elapsed=Math.max(0,Math.floor(((workout.finishedAt||Date.now())-(workout.startedAt||Date.now()))/1000));overlay.querySelectorAll('[data-session-clock]').forEach(el=>el.textContent=clock(elapsed));const left=Math.max(0,Math.ceil((restUntil-Date.now())/1000));overlay.querySelectorAll('[data-rest-clock]').forEach(el=>el.textContent=left?clock(left):'Jöhet a következő.');}
setInterval(updateTimers,500);
export function workoutContent(domain,page){
 if(domain!=='train'||![0,1,2].includes(page))return null;const m=metrics(workout),done=workout.status==='complete';
 if(page===0)return `<div class="training-hero"><span class="overline">SZERDA · 3. HÉT / 6</span><span class="training-status">${done?'✓ LEZÁRVA':m.count?'FOLYAMATBAN':'MAI EDZÉSED'}</span><h2>Felsőtest A</h2><p>Apránként több. Hétről hétre erősebb.</p>${diagram()}<div class="training-pills"><span>3 gyakorlat</span><span>${m.count} / 9 szett</span><span>2 RIR</span></div>${action(done?'Visszanézek az edzésemre ↗':m.count?'Folytatom az edzést →':'Kezdjük az edzést →','data-workout')}</div>
 <div class="training-context"><span>${icon('moon')}<b>7 ó 42 p</b><small>alvás</small></span><span>${icon('bowl')}<b>1 180 kcal</b><small>eddig ma</small></span><span>${icon('bolt')}<b>Holnap</b><small>röplabda</small></span></div>
 <div class="training-lineup"><div class="history-heading"><h2>A mai három</h2><span>Fókusz: felsőtest</span></div>${exercises.map((e,i)=>`<button data-workout-exercise="${i}"><span class="exercise-index">0${i+1}</span><span><strong>${e.name}</strong><small>3 × ${e.reps} · ${e.kg} kg · ${e.rir} RIR</small></span><b>${done?workout.sets[i].filter(Boolean).length+'/3':'↗'}</b></button>`).join('')}</div>
 <button class="load-door" data-route="train/1">${icon('ring')}<span><strong>A heted egyben</strong><small>Gym + röplabda + regeneráció</small></span><b>↗</b></button><button class="sport-door" data-sport>${icon('bolt')} Röplabda gyors logolása <b>＋</b></button>`;
 if(page===2)return `<div class="history-heading"><h2>Ezen a héten</h2><span>SZEPT. 7–13.</span></div><button class="load-door" data-workout>${icon('dumbbell')}<span><strong>Ma · Felsőtest A</strong><small>${done?'Lezárva':m.count?'Folyamatban':'Még előtted'} · ${m.count} szett${m.count?' · '+m.reps+' ismétlés':''}</small></span><b>↗</b></button><div class="load-door">${icon('bolt')}<span><strong>Kedd · Röplabda</strong><small>90 perc · RPE 7 · mintaelőzmény</small></span></div><div class="load-door">${icon('dumbbell')}<span><strong>Hétfő · Teljes test</strong><small>27 szett · 68 perc · mintaelőzmény</small></span></div>`;
 const rows=loadRows(workout);return `<div class="load-week"><span class="overline">3. HÉT · ALAPBÓL ERŐ</span><h2>Nem csak a gym számít.</h2><p>A munkád, a sportod és a pihenésed együtt.</p><div class="week-days">${['H','K','Sze','Cs','P','Szo','V'].map((d,i)=>`<span class="${i===2?'today':''}"><small>${d}</small>${icon(i===1||i===3?'bolt':i===0||i===2||i===4?'dumbbell':'moon')}<b>${i===0||i===1?'✓':i===2?(done?'✓':'MA'):'·'}</b></span>`).join('')}</div></div>
 <div class="load-summary"><span><b>${rows.reduce((sum,r)=>sum+r.done,0)}</b><small>logolt gym szett*</small></span><span><b>90′</b><small>röplabda eddig</small></span><span><b>7:42</b><small>utolsó alvás</small></span></div>
 ${done?`<div class="load-update">✓ A mai ${m.count} szetted már benne van.</div>`:m.count?`<div class="load-update">${m.count} mai szetted folyamatban van. Lezárás után kerül a heti összegbe.</div>`:''}
 <div class="history-heading"><h2>Izmonkénti volumen</h2><span>MUNKASOROZATOK</span></div><div class="load-legend"><span><i></i>Elvégezve</span><span><i></i>Heti terv</span><span><i></i>Célzóna</span></div>
 ${rows.map(r=>`<button class="muscle-load" data-muscle="${r.key}" style="--muscle-color:${r.color}"><span class="muscle-heading"><strong>${r.name}</strong><span><b>${r.done}</b> / ${r.plan}<small>szett</small></span></span><span class="muscle-track"><i class="zone-band" style="left:${r.low/20*100}%;width:${(r.high-r.low)/20*100}%"></i><i class="planned-bar" style="width:${r.plan/20*100}%"></i><i class="done-bar" style="width:${r.done/20*100}%"></i></span><span class="muscle-bottom"><span>${r.added?`Ma +${r.added} szett`:`${Math.max(0,r.plan-r.done)} szett a hátralévő tervben`}</span><span>${r.done>=r.low?'A mintazónában':'Még épül'} ↗</span></span></button>`).join('')}
 <div class="cross-load"><span class="overline">SPORT × REGENERÁCIÓ</span><h3>Holnap a pálya is kér belőled.</h3><div class="sport-load-pills"><span>Röplabda · 90 perc</span><span>Váll · közepes*</span><span>Láb · közepes*</span></div><p>A röplabdát külön jelöljük: nem váltjuk át gym szettekre. A vállad és a lábad érintettsége itt becslés.</p></div>
 <div class="coach-strip"><span class="coach-spark">✦</span><p>${done?'A mai terhelés bekerült. Holnap röplabda jön; a következő edzés előtt nézzünk rá arra is, hogyan aludtál.':'A heti tervben még van felsőtestmunka. A holnapi röplabda miatt a pihenésed is része a képnek.'}</p></div>
 <button class="load-door" data-route="me/2">${icon('moon')}<span><strong>Alvás és regeneráció</strong><small>A terhelés másik oldala</small></span><b>↗</b></button><p class="workout-footnote">* Bemutató alapadatok és célzónák. A mai lezárt szettek ténylegesen hozzáadódnak.<br>A sportbecslés és Mezo szövege nem élő AI-értékelés.</p>`;
}
export function initWorkout(options){callbacks=options;
 document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;
 if(el.hasAttribute('data-workout-exercise')){selected=Number(el.dataset.workoutExercise);editing=null;openWorkout();}
 if(el.hasAttribute('data-session-leave'))leave();
 if(el.hasAttribute('data-exercise')){selected=Number(el.dataset.exercise);editing=null;render();}
 if(el.hasAttribute('data-edit-set')){editing=Number(el.dataset.editSet);render();}
 if(el.hasAttribute('data-step')){const input=overlay.querySelector(`[name=${el.dataset.field}]`);const value=Number(input.value)+Number(el.dataset.step);input.value=String(Math.max(Number(input.min),Math.min(Number(input.max),value)));}
 if(el.hasAttribute('data-rest-skip')){restUntil=0;$('#rest-card').hidden=true;}
 if(el.hasAttribute('data-session-summary')){if(!metrics(workout).count)return;view='summary';restUntil=0;render();}
 if(el.hasAttribute('data-session-back')){workout.note=$('#closing-note')?.value||'';view='active';render();}
 if(el.hasAttribute('data-session-finish')){workout.note=$('#closing-note').value.trim();if(finishWorkout(workout)){view='complete';restUntil=0;render();react('celebrate',4000);}}
 if(el.hasAttribute('data-session-load')){leave();callbacks.go('train',1);}
 if(el.hasAttribute('data-muscle')){const r=loadRows(workout).find(r=>r.key===el.dataset.muscle);callbacks.detail(r.name,`${r.base} mintaelőzmény + ${r.added} ma lezárt szett = ${r.done} elvégzett szett. Heti terv: ${r.plan}. Bemutató célzóna: ${r.low}–${r.high}. A sportterhelést ettől külön kezeljük.`);}
 });
 document.addEventListener('submit',e=>{if(e.target.id!=='workout-set-form')return;e.preventDefault();const values=new FormData(e.target),index=editing??workout.sets[selected].findIndex(s=>!s);const changed=editing!==null;
 if(!logSet(workout,selected,index,Object.fromEntries(['kg','reps','rir'].map(k=>[k,Number(values.get(k))])))){ $('#set-error').textContent='Ellenőrizd a súlyt, ismétlést és a RIR értékét.';return;}
 editing=null;if(!changed)restUntil=Date.now()+exercises[selected].rest*1000;render();overlay.querySelector('.set-console').classList.add('just-logged');react('connect',1800);
 });
 $('#restart').addEventListener('click',()=>{workout=createWorkout();selected=0;editing=null;restUntil=0;leave();});
}

export const workoutSnapshot=()=>({complete:workout.status==='complete'});
